export function summarize(data: number[], meta: Meta): Summary {
  const total = data.reduce((sum, n) => sum + n, 0);
  const mean = data.length > 0 ? total / data.length : 0;
  return {
    metadata: meta,
    stats: { total, mean },
  };
}

