export function summarize(payload: number[], meta: Meta): Summary {
  const total = payload.reduce((sum, n) => sum + n, 0);
  const mean = payload.length > 0 ? total / payload.length : 0;
  return {
    metadata: meta,
    stats: { total, mean },
  };
}
